--
-- Purpose: build and lay out the dashboard and Genie space before real runs exist.
-- Every row is tagged so 04_cleanup_test_data.sql removes exactly these rows and nothing else:
--   lesson_id  = 'test-fortune-teller'      (lessons, steps, runs, events)
--   run_id     LIKE 'TEST-run-%'            (runs, events)
--   event_id   LIKE 'TEST-ev-%'             (events)
--   learner    = 'synthetic'                (runs)
--
-- Shape (generated, seeded, deterministic): one 8-step lesson (step 1 manual, step 5 is the flip),
-- 14 runs on Sat 2026-11-14 between 11:30 AM and 3:30 PM Madison time, before kickoff, so the 15-minute
-- "in progress" rule never applies to them. Built in:
--   * step 5 (flip) is the slowest relative to the expert, with the most manual advances and "behind" catches
--   * one "ahead" catch at step 3 (camera jumps 3 -> 5)
--   * two false passes at step 6 (camera pass, Back within 25 s)
--   * two abandoned runs at step 6 (one with run_end, one silent)
--   * one rate_limited breaker at step 7 (rest of that run by Next)
--   * about 3 % of checks time out (unsure, confidence 0, 3000 ms)
-- Insert order matches the module's flush order: lessons, steps, runs, events. Not idempotent: running it
-- twice duplicates events; run 04 first if unsure.




-- 919 events

-- Verify: expect lessons 1, steps 8, runs 14, events 919.
SELECT
  (SELECT count(*) FROM workspace.handover.lessons WHERE lesson_id = 'test-fortune-teller')  AS lessons,
  (SELECT count(*) FROM workspace.handover.steps   WHERE lesson_id = 'test-fortune-teller')  AS steps,
  (SELECT count(*) FROM workspace.handover.runs    WHERE run_id LIKE 'TEST-run-%') AS runs,
  (SELECT count(*) FROM workspace.handover.events  WHERE event_id LIKE 'TEST-ev-%') AS events;
