INSERT INTO workspace.handover.lessons (lesson_id, title, expert, duration_s, created_at) VALUES
  ('test-fortune-teller', 'Paper fortune teller (TEST DATA)', 'synthetic', 80.0, TIMESTAMP'2026-11-14 16:30:00.000Z');
INSERT INTO workspace.handover.steps (lesson_id, n, title, start_s, end_s, check_type, check_question) VALUES
  ('test-fortune-teller', 1, 'Lay the sheet flat, white side up', 0.0, 5.0, 'manual', ''),
  ('test-fortune-teller', 2, 'Fold corner to corner both ways', 5.0, 17.0, 'camera', 'Are there two diagonal creases forming an X?'),
  ('test-fortune-teller', 3, 'Fold all four corners to the centre', 17.0, 35.0, 'camera', 'Is the paper a smaller square with four triangles meeting in the middle?'),
  ('test-fortune-teller', 4, 'Crease the folds flat', 35.0, 41.0, 'camera', 'Are all four flaps pressed flat?'),
  ('test-fortune-teller', 5, 'Flip it over', 41.0, 45.0, 'camera', 'Is the smooth side with no flaps facing up?'),
  ('test-fortune-teller', 6, 'Fold the four new corners to the centre', 45.0, 62.0, 'camera', 'Are there four new triangles meeting in the middle?'),
  ('test-fortune-teller', 7, 'Fold it in half', 62.0, 68.0, 'camera', 'Is the paper a rectangle?'),
  ('test-fortune-teller', 8, 'Push the corners up and open it', 68.0, 80.0, 'camera', 'Are there four raised pockets?');
